30	impl Project {
31	    /// Copies `clip`'s pieces between each range's ends onto `track` at the
32	    /// same project times (this module's doc, spec §6, §11 SW-11).
33	    pub fn copy_pieces(
34	        &self,
35	        clip: u32,
36	        track: u32,
37	        ranges: &[[Ticks; 2]],
38	        video: Option<bool>,
39	        audio: Option<bool>,
40	    ) -> Result<Outcome, String> {
41	        let source = self.require_clip(clip)?.clone();
42	        let destination = self.require_track(track)?;
43	
44	        let mut spans: Vec<(Ticks, Ticks)> = ranges
45	            .iter()
46	            .map(|[a, b]| {
47	                let (low, high) = if a <= b { (*a, *b) } else { (*b, *a) };
48	                (self.snapped(low), self.snapped(high))
49	            })
50	            .filter(|(from, to)| to > from)
51	            .collect();
52	        if spans.is_empty() {
53	            return Ok(Outcome::Identity);
54	        }
55	        spans.sort_by_key(|&(from, to)| (from, to));
56	
57	        if let Some(why) = self.pieces_refusal(&source, destination.id, destination.locked, &spans)
58	        {
59	            return Ok(Outcome::Refused(why));
60	        }
61	
62	        let mut scratch = self.clone();
63	        scratch.clips = vec![source.clone()];
64	        let mut next = self.clone();
65	        let mut pieces: Vec<Clip> = Vec::with_capacity(spans.len());
66	        for &(from, to) in &spans {
67	            // `middle` answers `None` only when a cut is not strictly inside
68	            // the clip, which the checks above rule out (every span is
69	            // non-empty and inside the clip), so no range is ever skipped.
70	            let Some(mut piece) = middle(&scratch, &source, from, to) else {
71	                continue;
72	            };
73	            next.remint(&mut piece);
74	            piece.track = track;
75	            piece.start = from;
76	            piece.transition_in = None;
77	            piece.linked = None;
78	            if let Some(on) = video {
79	                piece.enabled.video = on;
80	            }
81	            if let Some(on) = audio {
82	                piece.enabled.audio = on;
83	            }
84	            pieces.push(piece);
85	        }
86	        next.clips.extend(pieces);
87	        self.finish(next)
88	    }
89	
90	    /// The first refusal SW-11 names for `spans` (ordered, snapped, sorted),
91	    /// in its order: a nest clip, a range outside the clip, overlapping
92	    /// ranges, a locked destination, a destination holding a clip.
93	    fn pieces_refusal(
94	        &self,
95	        source: &Clip,
96	        track: u32,
97	        locked: bool,
98	        spans: &[(Ticks, Ticks)],
99	    ) -> Option<String> {
100	        if matches!(source.source, Source::Nest { .. }) {
101	            return Some(format!(
102	                "clip {} is a nest: a piece of it would replay the nest from its first frame",
103	                source.id
104	            ));
105	        }
106	        let (start, end) = (source.start, clip_end(source));
107	        if let Some((from, to)) = spans.iter().find(|(from, to)| *from < start || *to > end) {
108	            return Some(format!(
109	                "range [{from}, {to}] is outside clip {}, which runs from {start} to {end}",
110	                source.id
111	            ));
112	        }
113	        if let Some(pair) = spans.windows(2).find(|pair| pair[0].1 > pair[1].0) {
114	            let ((a, b), (c, d)) = (pair[0], pair[1]);
115	            return Some(format!("ranges [{a}, {b}] and [{c}, {d}] overlap"));
116	        }
117	        if locked {
118	            return Some(locked_track(track, "no piece can be copied onto it"));
119	        }
120	        let holder = self.clips_on_track(track).into_iter().find(|held| {
121	            let held_end = clip_end(held);
122	            spans
123	                .iter()
124	                .any(|(from, to)| held.start < *to && held_end > *from)
125	        })?;
126	        Some(format!(
127	            "track {track} holds clip {} between {} and {}",
128	            holder.id,
129	            holder.start,
130	            clip_end(holder)
131	        ))
132	    }
133	}
