169	/// Switch by Speaker's values, as both doors take them (spec §11 SW-26 (d)): the ranges the sheet
170	/// clamps to and `switch_by_speaker` refuses outside of, the four values the sheet remembers, and
171	/// the summary the sheet shows. Pure but for the `UserDefaults` it is handed; names no `rc_*`.
172	extension SpeakerSwitch.Settings {
173	    /// Seconds.
174	    static let minShotRange: ClosedRange<Double> = 0.5...30
175	    /// Seconds; the tool's alone (SW-26 (d)).
176	    static let minTurnRange: ClosedRange<Double> = 0.2...10
177	    /// Seconds.
178	    static let leadRange: ClosedRange<Double> = 0...1
179	    /// dB below a speaker's own level.
180	    static let bleedRange: ClosedRange<Double> = 3...40
181	    /// dB; the tool's alone (SW-26 (d)).
182	    static let dominanceRange: ClosedRange<Double> = 0...30
183	    /// Seconds.
184	    static let wideAfterRange: ClosedRange<Double> = 2...600
185	    /// The sheet's field when "Cut to the wide after" is first ticked (the owner: offered, off).
186	    static let wideAfterOffered = 20.0
187	
188	    static let minShotKey = "FrameJobSwitchSpeakerMinShot"
189	    static let leadKey = "FrameJobSwitchSpeakerLead"
190	    /// "wide" or "hold".
191	    static let crosstalkKey = "FrameJobSwitchSpeakerCrosstalk"
192	    static let bleedKey = "FrameJobSwitchSpeakerBleed"
193	
194	    /// The sheet's opening values: each remembered key clamped into its range, an absent or
195	    /// unreadable key the default. Read through `double(forKey:)`, so a launch argument counts.
196	    static func remembered(_ d: UserDefaults) -> SpeakerSwitch.Settings {
197	        var s = SpeakerSwitch.Settings()
198	        func number(_ key: String, _ range: ClosedRange<Double>, _ fallback: Double) -> Double {
199	            guard d.object(forKey: key) != nil else { return fallback }
200	            let v = d.double(forKey: key)
201	            guard v.isFinite else { return fallback }
202	            return min(max(v, range.lowerBound), range.upperBound)
203	        }
204	        s.minShot = number(minShotKey, minShotRange, s.minShot)
205	        s.lead = number(leadKey, leadRange, s.lead)
206	        s.bleedDB = number(bleedKey, bleedRange, s.bleedDB)
207	        if let raw = d.string(forKey: crosstalkKey), let crosstalk = SpeakerSwitch.Crosstalk(rawValue: raw) {
208	            s.crosstalk = crosstalk
209	        }
210	        return s
211	    }
212	
213	    /// Writes only the remembered keys whose value differs from the sheet's opening values, so a
214	    /// sheet pressed as it opened moves no default (mcp.py's DEFAULTS MOVED guard).
215	    func remember(changedFrom opened: SpeakerSwitch.Settings, in d: UserDefaults) {
216	        if minShot != opened.minShot { d.set(minShot, forKey: Self.minShotKey) }
217	        if lead != opened.lead { d.set(lead, forKey: Self.leadKey) }
218	        if crosstalk != opened.crosstalk { d.set(crosstalk.rawValue, forKey: Self.crosstalkKey) }
219	        if bleedDB != opened.bleedDB { d.set(bleedDB, forKey: Self.bleedKey) }
220	    }
221	}
