223	extension SpeakerSwitch {
224	    /// "N shots: k on <name>, …. Adds M clips." — the angles in the order they first show,
225	    /// each named by `names` (a track id when it has none).
226	    static func summary(_ shots: [Shot], added: Int, names: [UInt32: String]) -> String {
227	        var order: [UInt32] = []
228	        var counts: [UInt32: Int] = [:]
229	        for shot in shots {
230	            if counts[shot.angle] == nil { order.append(shot.angle) }
231	            counts[shot.angle, default: 0] += 1
232	        }
233	        let each = order.map { "\(counts[$0] ?? 0) on \(names[$0] ?? "track \($0)")" }
234	        let count = shots.count == 1 ? "1 shot" : "\(shots.count) shots"
235	        let adds = added == 1 ? "1 clip" : "\(added) clips"
236	        return "\(count): \(each.joined(separator: ", ")). Adds \(adds)."
237	    }
238	
239	    /// The name each of `tracks` is listed by: its own, with " (n)" — n its 1-based position
240	    /// from the back — when two of them share it (SW-13's rule, `SwitchAngle.angles`).
241	    static func titles(_ tracks: [UInt32], in snapshot: ProjectSnapshot) -> [UInt32: String] {
242	        let names = tracks.map { snapshot.track($0)?.name ?? "Track" }
243	        var out: [UInt32: String] = [:]
244	        for (track, name) in zip(tracks, names) {
245	            if names.filter({ $0 == name }).count > 1 {
246	                out[track] = "\(name) (\((snapshot.trackIndex(of: track) ?? 0) + 1))"
247	            } else {
248	                out[track] = name
249	            }
250	        }
251	        return out
252	    }
253	
254	    /// The sheet's Microphone choices, front first: every track holding a selected `.media`
255	    /// clip with its sound on and a media with audio, a detached camera sound included (SW-20).
256	    static func microphoneChoices(_ selection: [ClipSnapshot], in snapshot: ProjectSnapshot)
257	        -> [UInt32]
258	    {
259	        snapshot.tracks.reversed().map(\.id).filter { track in
260	            selection.contains { clip in
261	                guard clip.track == track, case .media = clip.source, clip.enabled.audio else {
262	                    return false
263	                }
264	                return snapshot.media(for: clip)?.hasAudio == true
265	            }
266	        }
267	    }
268	}
