271	/// Switch by Speaker's planner (road map "creator-jobs" SW2a, spec §11
272	/// SW-20…SW-25): which microphone is active on a 10 ms grid, the shots those
273	/// turns make on the angle tracks, and every refusal named at once. Nothing
274	/// here is visible yet; SW2b's sheet and tool write the shots onto a Program
275	/// track.
276	///
277	/// Pure (SW-25): `defaults`, `plan`, `labels` and `shots` read no document,
278	/// file or clock. `read` (`SpeakerSwitch+Read.swift`) is the one reader, and
279	/// the series it builds are `ClipLevelSeries`'. Names no `rc_*` but
280	/// `ReelTime.snapToFrame` and `ReelTime.format`.
281	enum SpeakerSwitch {
282	    static let actionName = "Switch by Speaker"
283	    static let maxAngles = 9
284	
285	    /// What a qualifying crosstalk turn does: show the wide, or hold.
286	    enum Crosstalk: String { case wide, hold }
287	
288	    /// Seconds and dB; the defaults are SW-S4's (SW-21) and SW-22's drafts.
289	    struct Settings: Equatable {
290	        var minShot = 2.0, minTurn = 1.0, lead = 0.2, crosstalkMin = 1.0, bridge = 0.5
291	        var crosstalk: Crosstalk = .wide
292	        var bleedDB = 15.0, dominanceDB = 8.0, floorMarginDB = 6.0, voiceThreshold: Float = 0.5
293	        /// nil = off.
294	        var wideAfter: Double? = nil
295	        /// The faces mode's label (SW-81): the top angle's activity over the next's, and the
296	        /// floor it must exceed.
297	        var faceRatio = FaceActivity.ratio, faceFloor = FaceActivity.floor
298	    }
299	
300	    /// Who says who is talking (SW-83): each microphone its own person, or one microphone shared
301	    /// by two or more angles and their faces (`SpeakerSwitch+Faces.swift`).
302	    enum Mode: String { case microphones, faces }
303	
304	    /// One face-speaker angle's mouth activity on the range's grid (SW-81): step k's activity,
305	    /// nil where none can be read. Empty: not read.
306	    struct FaceAngle: Equatable {
307	        let track: UInt32
308	        let activity: [Double?]
309	    }
310	
311	    /// A person: their microphone track and the angle track that shows them.
312	    struct Speaker: Equatable { let mic: UInt32?; let angle: UInt32? }
313	    struct Pairing: Equatable { let speakers: [Speaker]; let wide: UInt32? }
314	    struct Span: Equatable { let clip: UInt32; let start: Ticks; let end: Ticks }
315	    /// An angle track and its picture clips (`SwitchAngle.pictureClips`), by start.
316	    struct AngleTrack: Equatable { let track: UInt32; let clips: [Span] }
317	
318	    /// One microphone track on the range's grid: step k is
319	    /// `[from + k·step, from + (k+1)·step)`. Empty arrays: not read.
320	    struct Microphone: Equatable {
321	        let track: UInt32
322	        /// ℓ(k) in dB over the centred window; −∞ when silent.
323	        let level: [Double]
324	        /// v(k).
325	        let voice: [Float]
326	        /// A selected clip of this track plays at the step's midpoint.
327	        let covered: [Bool]
328	    }
329	        if !refusals.isEmpty { return .refused(refusals) }
330	        let step = stepTicks
331	        let count = step > 0 ? Int(max(0, input.to - input.from) / step) : 0
332	        let faces = mode(input.pairing) == .faces
333	        let all = faces
334	            ? faceLabels(input)
335	            : labels(input.microphones.filter { $0.level.count == count }, settings: input.settings)
336	        let planned = shots(
337	            labels: all, from: input.from, to: input.to, fps: input.fps,
338	            pairing: faces ? facePairing(input.pairing) : input.pairing,
339	            angles: input.angles, settings: input.settings)
340	        let added = clipsAdded(planned, angles: input.angles, from: input.from, to: input.to)
341	        let most = Int(RC_MAX_CLIPS)
342	        if input.clipCount + added > most {
343	            return .refused([
344	                "Switch by Speaker would add \(added) clips to \(input.clipCount); the most is "
345	                    + "\(most) — raise the minimum shot."
346	            ])
347	        }
348	        return .planned(shots: planned, added: added)
349	    }
350	
351	    /// SW-24's list, in its order; empty when nothing is refused.
352	    static func refusals(_ input: Input) -> [String] {
353	        var out: [String] = []
354	        let angles = input.angles.map(\.track)
355	        if angles.count < 2 {
356	            out.append(
357	                "Switch by Speaker needs at least two angles: tracks holding a selected clip "
358	                    + "with a picture.")
359	        }
360	        if angles.count > maxAngles {
361	            out.append(
362	                "Switch by Speaker takes at most nine angles; \(angles.count) tracks hold a "
363	                    + "selected clip with a picture.")
364	        }
365	        let microphones = input.microphones.map(\.track)
366	        let faces = mode(input.pairing) == .faces
367	        // SW-83: in the faces mode a speaker on the wide takes no part.
368	        for speaker in input.pairing.speakers
369	        where !(faces && speaker.angle != nil && speaker.angle == input.pairing.wide) {
370	            guard let mic = speaker.mic, microphones.contains(mic) else {
371	                let track = speaker.angle ?? speaker.mic ?? 0
372	                out.append("The speaker on track \(track) has no microphone.")
373	                continue
374	            }
375	            if speaker.angle.map({ !angles.contains($0) }) ?? true {
376	                out.append("The microphone on track \(mic) has no angle to show its speaker.")
377	            }
378	        }
379	        var counted: [UInt32] = []
