386	                        + "own microphone.")
387	            }
388	        }
389	        out += input.problems
390	        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
391	        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
392	        let b = ReelTime.format(input.to, fps: input.fps, frames: true)
