411	    /// SW-24's no-speech sentences: each read microphone with no speech step inside the range.
412	    static func silentMicrophones(_ input: Input) -> [String] {
413	        var out: [String] = []
414	        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
415	        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
416	        let b = ReelTime.format(input.to, fps: input.fps, frames: true)
417	        for mic in input.microphones where mic.voice.count == count {
418	            let speaks = mic.voice.indices.contains {
