1	//! `copy_pieces` — a clip's pieces between given project times copied onto
2	//! another track at the same times (road map "creator-jobs" SW1, spec §11
3	//! SW-11, SW-12). It is the primitive Clip ▸ Switch Angle ▸ writes with: a
4	//! piece of a synced angle shows the angle's own frame at every time.
5	//!
6	//! A piece is EXACTLY the middle a `split` at its two ends would leave —
7	//! its source window, a ramp's map and rate, its actions clipped, a
8	//! graphic's `in` and `length`, its words rebased — because it is made by
9	//! `edit_split.rs`'s `split_clip` itself, on a scratch copy holding only the
10	//! source clip. This module states none of those rules; it only says where
11	//! the middle lands: a fresh id and fresh action ids from the result's own
12	//! counter, `track` the destination, `start` the range's start, no
13	//! transition and no link, and `enabled` overridden where `video`/`audio`
14	//! are given.
15	//!
16	//! In order (SW-11): `Err` for an unknown clip, then for an unknown track;
17	//! each pair put in order and snapped, a range empty on the grid dropped
18	//! (nothing left is an identity), the rest sorted by start; then the
19	//! refusals — a nest clip, a range outside the clip, overlapping ranges, a
20	//! locked destination, a destination holding a clip over a range. The exit
21	//! is `finish`.
22	
23	use crate::edit_clip::clip_end;
24	use crate::edit_split::split_clip;
25	use crate::edit_time::locked_track;
26	use crate::model::{Clip, Project, Source};
27	use crate::outcome::Outcome;
28	use crate::time::Ticks;
29	
30	impl Project {
31	    /// Copies `clip`'s pieces between each range's ends onto `track` at the
32	    /// same project times (this module's doc, spec §6, §11 SW-11).
33	    pub fn copy_pieces(
34	        &self,
35	        clip: u32,
36	        track: u32,
37	        ranges: &[[Ticks; 2]],
38	        video: Option<bool>,
39	        audio: Option<bool>,
40	    ) -> Result<Outcome, String> {
41	        let source = self.require_clip(clip)?.clone();
42	        let destination = self.require_track(track)?;
43	
44	        let mut spans: Vec<(Ticks, Ticks)> = ranges
45	            .iter()
46	            .map(|[a, b]| {
47	                let (low, high) = if a <= b { (*a, *b) } else { (*b, *a) };
48	                (self.snapped(low), self.snapped(high))
49	            })
50	            .filter(|(from, to)| to > from)
51	            .collect();
52	        if spans.is_empty() {
53	            return Ok(Outcome::Identity);
54	        }
55	        spans.sort_by_key(|&(from, to)| (from, to));
56	
57	        if let Some(why) = self.pieces_refusal(&source, destination.id, destination.locked, &spans)
58	        {
59	            return Ok(Outcome::Refused(why));
60	        }
61	
62	        let mut scratch = self.clone();
63	        scratch.clips = vec![source.clone()];
64	        let mut next = self.clone();
65	        let mut pieces: Vec<Clip> = Vec::with_capacity(spans.len());
66	        for &(from, to) in &spans {
67	            // `middle` answers `None` only when a cut is not strictly inside
68	            // the clip, which the checks above rule out (every span is
69	            // non-empty and inside the clip), so no range is ever skipped.
70	            let Some(mut piece) = middle(&scratch, &source, from, to) else {
71	                continue;
72	            };
73	            next.remint(&mut piece);
74	            piece.track = track;
75	            piece.start = from;
76	            piece.transition_in = None;
77	            piece.linked = None;
78	            if let Some(on) = video {
79	                piece.enabled.video = on;
80	            }
81	            if let Some(on) = audio {
82	                piece.enabled.audio = on;
83	            }
84	            pieces.push(piece);
85	        }
86	        next.clips.extend(pieces);
87	        self.finish(next)
88	    }
