430	    /// The first stretch of `[from, to)` no angle covers.
431	    static func firstGap(_ angles: [AngleTrack], from: Ticks, to: Ticks)
432	        -> (from: Ticks, to: Ticks)?
433	    {
434	        var t = from
435	        while t < to {
436	            if let end = angles.compactMap({ reach($0, from: t) }).max() {
437	                t = end
438	                continue
439	            }
440	        var out: [[UInt32]] = []
441	        out.reserveCapacity(count)
442	        for k in 0..<count {
443	            var active: [(track: UInt32, over: Double)] = []
444	            for (index, mic) in microphones.enumerated() {
445	                guard let gauge = gauges[index], mic.covered[k], mic.voice[k] >= threshold
446	                else { continue }
447	                let level = mic.level[k]
448	                guard level >= gauge.p - settings.bleedDB,
449	                    level >= gauge.f + settings.floorMarginDB
450	                else { continue }
451	                active.append((mic.track, level - gauge.p))
452	            }
453	            if active.count >= 2, let top = active.max(by: { $0.over < $1.over }),
454	                active.allSatisfy({ $0.track == top.track
455	                    || top.over - $0.over >= settings.dominanceDB })
456	            {
457	                active = [top]
458	            }
459	            out.append(active.map(\.track))
460	        }
461	        return out
462	    }
